import {GestureController,GESTURE_TUNING} from './GestureController.js';
import {BattingIntentController} from './BattingIntentController.js';
import {ballContext} from './BallContext.js';
import {clamp} from '../physics.js';
export class GestureInput {
 constructor(owner){this.owner=owner;this.gesture=new GestureController();this.resolver=new BattingIntentController();this.virtual={x:.5,y:.55};this.reset();try{const saved=JSON.parse(localStorage.getItem('crease-gesture-calibration')||'null');if(saved?.typicalSpeed>0)this.gesture.calibration={...this.gesture.calibration,...saved};}catch{}}
 reset(){this.gesture.reset();this.resolver.reset();this.intent=null;this.fired=false;this.lastClock=-1;this.contextClock=-1;this.pointer=null;this.completed=[];this.lastPhase=0;}
 begin(x,y,t,source){const o=this.owner;if(!o.active)return;this.fired=o.poseController.human.active;if(!this.fired)this.resolver.reset();this.gesture.begin(x,y,t,o.hand,source);this.lastClock=o.clock;this.virtual={x,y};this.update();}
 sample(x,y,t){if(!this.gesture.active)return;this.lastClock=this.owner.clock;this.gesture.sample(x,y,t);this.update();}
 end(t,cancel=false){this.gesture.end(t,cancel);this.update();if(this.gesture.features){this.completed.push({...this.gesture.features});if(this.completed.length>12)this.completed.shift();}this.pointer=null;}
 update(){const o=this.owner,f=this.gesture.features;if(!f)return;const context=this.contextOverride||ballContext(o.poseController.human.observation,o.foot),body={hand:o.hand,foot:o.foot,commitment:o.poseController.human.active?clamp(o.poseController.human.phase/.48,0,1):0,manualFeet:o.keys.size>0};this.context=context;this.intent=o.gestureStyle&&o.gestureStyle!=='auto'?this.resolver.fromButton(o.gestureStyle,f.effort,body):this.resolver.resolve(f,context,body);this.intent.effort=clamp(this.intent.effort*o.sensitivity,.15,1);this.intent.preparation=clamp(f.totalDistance/.12,0,1);this.intent.released=!this.gesture.active;this.intent.abort=!!f.cancelled;this.intent.commitTime=this.commitTime??null;
 if(!this.fired&&f.totalDistance>=GESTURE_TUNING.minimumDistance&&f.duration>=GESTURE_TUNING.minimumDuration){this.fired=true;this.commitTime=o.clock;o.swing(this.intent.effort);this.intent.commitTime=this.commitTime;}o.onGesture?.(this.gesture,this.intent,context);}
 step(){const o=this.owner,g=this.gesture;if(g.active&&['mouse','trackpad'].includes(g.source)&&o.clock-this.lastClock>(g.source==='mouse'?GESTURE_TUNING.mouseIdle:GESTURE_TUNING.wheelIdle))this.end(g.samples.at(-1).timestamp+.12);if(g.features&&o.clock-this.contextClock>.02){this.contextClock=o.clock;this.update();}if(this.intent){this.intent.abort=this.intent.abort||o.leave;this.intent.footworkIntent={...this.intent.footworkIntent,...o.foot};}}
 button(effort=.65){const o=this.owner;this.intent=this.resolver.fromButton(o.gestureStyle==='auto'?'straight':o.gestureStyle||'straight',effort,{hand:o.hand,foot:o.foot});this.intent.released=true;o.swing(effort);}
 attach(canvas,{isBlocked=()=>false,onPause=()=>{},onLeave=()=>{}}={}){const o=this.owner,coords=e=>{const r=canvas.getBoundingClientRect();const scale=Math.min(r.width,r.height);return {x:.5+(e.clientX-r.left-r.width/2)/scale,y:.5+(e.clientY-r.top-r.height/2)/scale};},blocked=()=>isBlocked()||!o.active;
 canvas.addEventListener('pointerdown',e=>{if(blocked()||e.button===2||o.mode==='trackpad')return;if(e.pointerType==='mouse'&&o.mode!=='mouse')return;if(this.pointer!==null)return;const p=coords(e);this.pointer=e.pointerId;canvas.setPointerCapture?.(e.pointerId);this.begin(p.x,p.y,e.timeStamp/1000,e.pointerType==='mouse'?'mouse':'touch');});
 canvas.addEventListener('pointermove',e=>{if(blocked()||e.buttons===2)return;const p=coords(e);if(o.mode==='trackpad'){if(!this.gesture.active)this.virtual=p;return;}if(e.pointerType==='mouse'&&o.mode==='mouse'){const prev=this.previousMouse;this.previousMouse={...p,t:e.timeStamp/1000};if(!this.gesture.active){if(!prev||Math.hypot(p.x-prev.x,p.y-prev.y)<.004)return;this.begin(prev.x,prev.y,prev.t,'mouse');}this.sample(p.x,p.y,e.timeStamp/1000);}else if(this.pointer===e.pointerId)this.sample(p.x,p.y,e.timeStamp/1000);});
 for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,e=>{if(this.pointer===e.pointerId&&this.gesture.active)this.end(e.timeStamp/1000,type!=='pointerup');});canvas.addEventListener('pointerleave',()=>{this.previousMouse=null;});
 canvas.addEventListener('wheel',e=>{if(blocked()||o.mode!=='trackpad'||e.ctrlKey||e.metaKey)return;e.preventDefault();const r=canvas.getBoundingClientRect(),unit=e.deltaMode===1?16:e.deltaMode===2?r.height:1,sign=o.invert?-1:1;if(!this.gesture.active)this.begin(this.virtual.x,this.virtual.y,e.timeStamp/1000-.001,'trackpad');this.virtual={x:clamp(this.virtual.x+e.deltaX*unit/Math.min(r.width,r.height)*sign*o.sensitivity,-.5,1.5),y:clamp(this.virtual.y+e.deltaY*unit/Math.min(r.width,r.height)*sign*o.sensitivity,-.5,1.5)};this.sample(this.virtual.x,this.virtual.y,e.timeStamp/1000);},{passive:false});
 document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target?.tagName||''))return;if(e.code==='KeyP'&&!e.repeat){onPause();return;}if(blocked()||(e.target?.tagName==='BUTTON'&&['Space','Enter'].includes(e.code)))return;o.keys.add(e.code);if(e.code==='Space'){e.preventDefault();o.leave=true;if(this.intent)this.intent.abort=true;onLeave();}if(e.code==='Enter'&&!e.repeat)this.button();});document.addEventListener('keyup',e=>o.keys.delete(e.code));
 }
}
